type Overview = z.infer<typeof OverviewGetOutputSchema>;
type RawQueue = Parameters<typeof queueRow>[0];
const cid = ConnectionIdSchema.parse('c1');
const UNREADABLE = 'The alarm state could not be read.';

/** Five queues whose counts add up to 30 messages, 15 ready and 15 unacknowledged. */
const five = (): RawQueue[] =>
  [1, 2, 3, 4, 5].map((n) => ({
    name: `q${String(n)}`,
    vhost: '/',
    messages: 2 * n,
    messages_ready: n,
    messages_unacknowledged: n,
  }));

/** The index a finished (or partial) queue sweep leaves behind. */
function indexOf(queues: RawQueue[], complete = true) {
  const index = createInventoryIndex(DEFAULT_EXPLORER_LIMITS);
  const meta = { sweptAt: 5_000, complete };
  index.installAll([
    { kind: 'queues', rows: queues.map(queueRow), meta },
    { kind: 'exchanges', rows: [], meta },
    { kind: 'connections', rows: [], meta },
  ]);
  return index;
}
const sweeperOf = (index?: ReturnType<typeof indexOf>) => ({
  touch: vi.fn(),
  index: () => index,
  status: () => ({
    sweeping: false,
    expected: new Map<SweptKind, number>(),
  }),
});

async function overviewOf(
  mgmt: MgmtReadPort,
  sweeper?: ReturnType<typeof sweeperOf>,
): Promise<Overview> {
  const engine = createTestExecutor();
  engine.executor.register(
    createOverviewGetAction({
      ...createExplorerFakeDeps(),
      mgmt,
      clock: createManualClock(7_000),
      sweeper: sweeper ?? sweeperOf(),
    }),
  );
  const done = await engine.executor.run(def, sampleInput, createTestContext());
  if (done.kind !== 'output') throw new Error(`expected output: ${done.kind}`);
  return def.output.parse(done.output);
}

const routed = (routes: Partial<OverviewRoutes>) =>
  withRoutes(createScriptedBroker(), routes);
const node = (name: string, mem?: boolean, disk?: boolean) => ({
  name,
  running: true,
  ...(mem === undefined ? {} : { mem_alarm: mem }),
  ...(disk === undefined ? {} : { disk_free_alarm: disk }),
});
/** The recorded overview of 4.2.9 with the named members removed. */
function without(...members: string[]): unknown {
  const answer = structuredClone(
    golden('4.2.9', 'stats-on')['/api/overview'],
  ) as Record<string, unknown>;
  for (const member of members) Reflect.deleteProperty(answer, member);
  return answer;
}

describe('explorer overview', () => {
  it('AC-11 explorer overview on 4.2.9 stats off sums the queue totals and labels rates unavailable', async () => {
    const mgmt = routed(golden('4.2.9', 'stats-off'));

    const full = await overviewOf(mgmt, sweeperOf(indexOf(five())));

    expect(full).toMatchObject({
      product: 'RabbitMQ',
      version: '4.2.9',
      clusterName: 'rabbit@lab-node',
      totals: {
        queues: 5,
        exchanges: 20,
        connections: 1,
        messages: {
          total: 30,
          ready: 15,
          unacknowledged: 15,
          source: 'queue-sweep',
          asOf: 5_000,
          complete: true,
        },
      },
      rates: { state: 'unavailable', reason: 'statistics-off' },
      nodes: [{ name: 'rabbit@lab-node', running: true, beingDrained: false }],
      freshness: { state: 'live', sweptAt: 5_000, complete: true, loaded: 5 },
    });
    // The stats-off overview carries no channel or consumer count, so none is made up.
    expect(full.totals).not.toHaveProperty('channels');
    expect(full.totals).not.toHaveProperty('consumers');

    // A partial sweep, and a queue that sent no counts, make the sum incomplete (never a zero).
    const partial = await overviewOf(mgmt, sweeperOf(indexOf(five(), false)));
    expect(partial.totals.messages).toMatchObject({
      total: 30,
      complete: false,
    });
    expect(partial.freshness.complete).toBe(false);
    const silent = indexOf([...five(), { name: 'qx', vhost: '/' }]);
    expect(
      (await overviewOf(mgmt, sweeperOf(silent))).totals.messages,
    ).toMatchObject({ total: 30, complete: false });

    // Before the first sweep there is no sum to give: absent, and the freshness says loading;
    // with no index at all (the module was stopped) it says unavailable.
    const loading = await overviewOf(
      mgmt,
      sweeperOf(createInventoryIndex(DEFAULT_EXPLORER_LIMITS)),
    );
    expect(loading.totals).not.toHaveProperty('messages');
    expect(loading.freshness).toMatchObject({
      state: 'loading',
      complete: false,
      loaded: 0,
      expected: 5,
    });
    const gone = await overviewOf(mgmt, sweeperOf());
    expect(gone.totals).not.toHaveProperty('messages');
    expect(gone.freshness).toMatchObject({
      state: 'unavailable',
      complete: false,
    });
  });

  it('AC-12 explorer overview on stats on reads the broker totals and rates and never invents zeros', async () => {
    const swept = sweeperOf(indexOf(five()));

    const on = await overviewOf(routed(golden('4.2.9', 'stats-on')), swept);
    expect(on.totals).toMatchObject({
      channels: 1,
      consumers: 1,
      // The broker's own totals win over the sweep's sums, and are as old as the answer.
      messages: {
        total: 11,
        ready: 9,
        unacknowledged: 2,
        source: 'broker-overview',
        asOf: 7_000,
        complete: true,
      },
    });
    expect(on.rates).toEqual({
      state: 'available',
      source: 'broker-overview',
      publishPerSec: 2.2,
      deliverPerSec: 0,
    });

    const lavin = await overviewOf(routed(golden('lavinmq-2.10.2', 'default')));
    expect(lavin).toMatchObject({
      product: 'LavinMQ',
      version: '2.10.2',
      totals: { channels: 1, consumers: 1, messages: { total: 8, ready: 6 } },
      rates: { state: 'available', publishPerSec: 1.6, deliverPerSec: 0.4 },
    });

    // A broker that reports no rates and no totals: unavailable, and no number appears.
    const bare = await overviewOf(
      routed({
        ...golden('4.2.9', 'stats-on'),
        '/api/overview': without('message_stats', 'queue_totals'),
      }),
    );
    expect(bare.rates).toEqual({
      state: 'unavailable',
      reason: 'not-reported',
    });
    expect(bare.totals).not.toHaveProperty('messages');
  });

  // The alarm shape is ASSUMED: no recording holds an alarm (spec Q-8), so the node flags
  // `mem_alarm` and `disk_free_alarm` are scripted. A recording replaces them in a follow-up.
  it('AC-13 explorer overview names the node and the resource of an alarm', async () => {
    const broker = createScriptedBroker();
    const mgmt = withRoutes(broker, {
      ...golden('4.2.9', 'stats-on'),
      '/api/nodes': [
        node('rabbit@a', true, false),
        node('rabbit@b', false, true),
        node('rabbit@c', false, false),
      ],
    });

    const { alarms } = await overviewOf(mgmt);

    expect(alarms).toEqual({
      state: 'active',
      active: [
        { node: 'rabbit@a', resource: 'memory' },
        { node: 'rabbit@b', resource: 'disk' },
      ],
    });
    // The nodes answered for the alarms, so no alarm check was needed.
    expect(broker.requests.map((r) => r.path).sort()).toEqual([
      '/api/nodes',
      '/api/overview',
    ]);
    const quiet = await overviewOf(
      routed({
        ...golden('4.2.9', 'stats-on'),
        '/api/nodes': [node('rabbit@a', false, false)],
      }),
    );
    expect(quiet.alarms).toEqual({ state: 'none' });
  });

  it('AC-14 explorer overview never reports no alarms when the alarm state could not be read', async () => {
    const off = golden('4.2.9', 'stats-off');
    const cases: Record<string, Partial<OverviewRoutes>> = {
      'the alarm check answers 503': {
        ...off,
        '/api/health/checks/alarms': brokerFailure(503),
      },
      'an unparsable body': {
        ...off,
        '/api/health/checks/alarms': '<html>secret-broker-text</html>',
      },
      'no alarm fields at all': { ...off, '/api/health/checks/alarms': {} },
      'a broker without the check': golden('lavinmq-2.10.2', 'default'),
      'flags on some nodes only': {
        ...off,
        '/api/nodes': [node('rabbit@a', false, false), node('rabbit@b')],
        '/api/health/checks/alarms': brokerFailure(503),
      },
    };
    for (const [name, routes] of Object.entries(cases)) {
      const out = await overviewOf(routed(routes));
      expect(out.alarms, name).toEqual({
        state: 'unknown',
        reason: UNREADABLE,
      });
      expect(JSON.stringify(out), name).not.toContain('secret-broker-text');
    }
    // The control: the same stats-off nodes with an alarm check that says ok are `none`, so the
    // cases above are unknown because of what was read, not by default.
    expect((await overviewOf(routed(off))).alarms).toEqual({ state: 'none' });
  });

  it('AC-15 explorer overview pre-empts the sweep and never lists the inventory', async () => {
    const clock = createManualClock();
    const timers = createManualTimers(clock);
    const scheduler = new BrokerScheduler({ clock, timers });
    const broker = createScriptedBroker({ queueCount: 2_500 });
    const inner = withRoutes(broker, golden('4.2.9', 'stats-off'));
    let background = 0;
    let widest = 0;
    // Every answer takes 30 ms of manual time, so requests that overlap would be seen.
    const slow: MgmtReadPort = {
      stream: (request, signal) => inner.stream(request, signal),
      get: async (request, signal) => {
        const isBackground = request.lane === 'background';
        background += isBackground ? 1 : 0;
        widest = Math.max(widest, background);
        const answer = await inner.get(request, signal);
        await new Promise<void>((resolve) => timers.setTimer(resolve, 30));
        background -= isBackground ? 1 : 0;
        return answer;
      },
    };
    const mgmt = scheduleMgmtRead(slow, scheduler);
    const sweeper = createSweeper({ mgmt, clock, timers });
    sweeper.touch(cid); // the sweep starts in the background lane
    const aborted = new AbortController();
    for (const page of [1, 2, 3]) {
      void mgmt
        .get(
          {
            connectionId: cid,
            path: '/api/queues/%2F',
            query: { page, page_size: 500 },
            schema: QueuePageSchema,
            lane: 'background',
          },
          aborted.signal,
        )
        .catch(() => undefined);
    }
    await timers.advance(0);
    const engine = createTestExecutor();
    engine.executor.register(
      createOverviewGetAction({
        ...createExplorerFakeDeps(),
        mgmt,
        clock,
        sweeper,
      }),
    );

    let overview: Overview | undefined;
    void engine.executor
      .run(def, sampleInput, createTestContext())
      .then((done) => {
        if (done.kind === 'output') overview = def.output.parse(done.output);
      });
    for (let i = 0; i < 100 && overview === undefined; i++) {
      await timers.advance(10);
    }

    expect(overview).toBeDefined();
    const lanes = broker.requests.map((r) => r.lane);
    const interactive = broker.requests.filter((r) => r.lane === 'interactive');
    // Three reads at most, all interactive, none of them a list of the inventory.
    expect(interactive.map((r) => r.path).sort()).toEqual([
      '/api/health/checks/alarms',
      '/api/nodes',
      '/api/overview',
    ]);
    // Only the background request already in flight came before the overview's last read.
    const before = broker.requests
      .slice(0, lanes.lastIndexOf('interactive'))
      .filter((r) => r.lane === 'background');
    expect(before.map((r) => r.path)).toEqual(['/api/vhosts']);

    // Then the sweep and the queued pages carry on, one background request at a time.
    for (let i = 0; i < 400; i++) await timers.advance(50);
    expect(
      broker.requests.filter((r) => r.path.startsWith('/api/queues/')).length,
    ).toBeGreaterThanOrEqual(4);
    expect(widest).toBe(1);
    const stopped = sweeper.stop();
    aborted.abort();
    await timers.advance(1_000);
    await stopped;
  });

  it('AC-16 explorer overview.get denies by default and hides connections the caller cannot see', async () => {
    const fake = createExplorerFakeDeps(); // a private connection of user-1
    const sweeper = sweeperOf();
    const fail = async (
      engine: TestExecutor,
      input: unknown,
      ctx: Parameters<typeof createTestContext>[0] = {},
    ) => {
      engine.executor.register(
        createOverviewGetAction({ ...fake, mgmt: fake.broker.read, sweeper }),
      );
      return engine.executor.run(def, input, createTestContext(ctx)).then(
        () => {
          throw new Error('expected a refusal');
        },
        (error: unknown) => error as AppError,
      );
    };

    const denied = await fail(
      createTestExecutor({
        executor: {
          authorizer: createRoleAuthorizer({ operator: ['broker.read'] }),
        },
      }),
      sampleInput,
      { principal: createTestPrincipal({ roles: ['intruder'] }) },
    );
    expect(denied.code).toBe('FORBIDDEN_RBAC');

    const stranger = await fail(createTestExecutor(), sampleInput, {
      principal: createTestPrincipal({ id: 'user-2' }),
    });
    const unknown = await fail(createTestExecutor(), { cid: 'nobody' });
    expect(stranger.code).toBe('NOT_FOUND');
    expect(unknown.code).toBe('NOT_FOUND');
    expect(stranger.detail).toBe(unknown.detail);

    // Nothing reached the broker, and no sweep was asked for.
    expect(fake.broker.requests).toEqual([]);
    expect(sweeper.touch).not.toHaveBeenCalled();
  });
});
